import{_ as a,o as l,c as o,a as i}from"./app.DLPSkIGI.js";const u=JSON.parse('{"title":"Governance Rollout Roadmap (DAG)","description":"","frontmatter":{},"headers":[],"relativePath":"governance/GOVERNANCE_ROADMAP_DAG.md","filePath":"governance/GOVERNANCE_ROADMAP_DAG.md","lastUpdated":1771823011000}'),t={name:"governance/GOVERNANCE_ROADMAP_DAG.md"};function r(n,e,c,d,s,h){return l(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="governance-rollout-roadmap-dag" tabindex="-1">Governance Rollout Roadmap (DAG) <a class="header-anchor" href="#governance-rollout-roadmap-dag" aria-label="Permalink to &quot;Governance Rollout Roadmap (DAG)&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Implement policy-driven multi-agent governance that avoids rigid <code>1 agent = 1 worktree</code>.</p><h2 id="phased-wbs" tabindex="-1">Phased WBS <a class="header-anchor" href="#phased-wbs" aria-label="Permalink to &quot;Phased WBS&quot;">​</a></h2><h3 id="phase-a0-delegation-architecture" tabindex="-1">Phase A0: Delegation Architecture <a class="header-anchor" href="#phase-a0-delegation-architecture" aria-label="Permalink to &quot;Phase A0: Delegation Architecture&quot;">​</a></h3><ol><li>A0.1 Publish classifier schema.</li><li>A0.2 Publish Ln delegation contract template.</li><li>A0.3 Publish domain playbooks.</li></ol><h3 id="phase-a-worktree-and-commit-policy" tabindex="-1">Phase A: Worktree and Commit Policy <a class="header-anchor" href="#phase-a-worktree-and-commit-policy" aria-label="Permalink to &quot;Phase A: Worktree and Commit Policy&quot;">​</a></h3><ol><li>A1.1 Publish scale-to-worktree matrix.</li><li>A1.2 Publish commit/micro-commit/pkg policy.</li><li>A1.3 Publish PR branch topology and merge rules.</li></ol><h3 id="phase-b-scheduler-and-placement" tabindex="-1">Phase B: Scheduler and Placement <a class="header-anchor" href="#phase-b-scheduler-and-placement" aria-label="Permalink to &quot;Phase B: Scheduler and Placement&quot;">​</a></h3><ol><li>B1.1 Build placement engine for <code>shared_lane</code>, <code>burst_isolated</code>, <code>integration</code>.</li><li>B1.2 Add overlap-risk scoring and escalation.</li><li>B1.3 Add lease/TTL for active assignments.</li></ol><h3 id="phase-c-concurrency-and-conflict-handling" tabindex="-1">Phase C: Concurrency and Conflict Handling <a class="header-anchor" href="#phase-c-concurrency-and-conflict-handling" aria-label="Permalink to &quot;Phase C: Concurrency and Conflict Handling&quot;">​</a></h3><ol><li>C1.1 Add file-claim registry.</li><li>C1.2 Add conflict fork retention policy.</li><li>C1.3 Add pkg-aware lock semantics.</li></ol><h3 id="phase-d-protocol-layering" tabindex="-1">Phase D: Protocol Layering <a class="header-anchor" href="#phase-d-protocol-layering" aria-label="Permalink to &quot;Phase D: Protocol Layering&quot;">​</a></h3><ol><li>D1.1 Define MCP tool/data boundaries.</li><li>D1.2 Define A2A task handoff boundaries.</li><li>D1.3 Define internal scheduler control API.</li></ol><h3 id="phase-e-observability-and-slos" tabindex="-1">Phase E: Observability and SLOs <a class="header-anchor" href="#phase-e-observability-and-slos" aria-label="Permalink to &quot;Phase E: Observability and SLOs&quot;">​</a></h3><ol><li>E1.1 Add trace propagation policy.</li><li>E1.2 Instrument delegation and conflict metrics.</li><li>E1.3 Add SLO dashboards and alerts.</li></ol><h3 id="phase-f-enforcement" tabindex="-1">Phase F: Enforcement <a class="header-anchor" href="#phase-f-enforcement" aria-label="Permalink to &quot;Phase F: Enforcement&quot;">​</a></h3><ol><li>F1.1 Add policy checks in pre-commit/pre-push.</li><li>F1.2 Add CI policy checks for branch/worktree metadata.</li><li>F1.3 Add policy exception workflow and audit trail.</li></ol><h3 id="phase-g-rollout" tabindex="-1">Phase G: Rollout <a class="header-anchor" href="#phase-g-rollout" aria-label="Permalink to &quot;Phase G: Rollout&quot;">​</a></h3><ol><li>G1.1 Pilot on 10 percent of lanes.</li><li>G1.2 Expand to 50 percent with measured tuning.</li><li>G1.3 Enforce 100 percent policy coverage.</li></ol><h2 id="dependency-dag" tabindex="-1">Dependency DAG <a class="header-anchor" href="#dependency-dag" aria-label="Permalink to &quot;Dependency DAG&quot;">​</a></h2><ol><li>A0.1 -&gt; A0.2 -&gt; A0.3</li><li>A0.1 -&gt; A1.1</li><li>A1.1 -&gt; A1.2 -&gt; A1.3</li><li>A1.1 -&gt; B1.1</li><li>B1.1 -&gt; B1.2 -&gt; B1.3</li><li>B1.2 -&gt; C1.1 -&gt; C1.2 -&gt; C1.3</li><li>A0.1 -&gt; D1.1 -&gt; D1.2 -&gt; D1.3</li><li>C1.1 + D1.3 -&gt; E1.1 -&gt; E1.2 -&gt; E1.3</li><li>A1.3 + C1.3 + E1.2 -&gt; F1.1 -&gt; F1.2 -&gt; F1.3</li><li>F1.2 + E1.3 -&gt; G1.1 -&gt; G1.2 -&gt; G1.3</li></ol>',22)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
